TLM.f("Sancti/02-27",{"officium":"S. Gabrielis a Virgine Perdolente Confessoris","rule":["vide C5;;","9 lectiones"],"fallback":"Commune/C5","sections":{"Introitus":[{"k":"ref","la":"Eccli 11:13"},{"k":"text","la":"Oculus Dei respéxit illum in bono, et eréxit eum ab humilitáte ipsíus, et exaltávit caput ejus: et miráti sunt in illo multi et honoravérunt Deum. (Allelúja, allelúja)"},{"k":"ref","la":"Ps 72:1"},{"k":"text","la":"Quam bonus Israël Deus his, qui recto sunt corde!"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Oculus Dei respéxit illum in bono, et eréxit eum ab humilitáte ipsíus, et exaltávit caput ejus: et miráti sunt in illo multi et honoravérunt Deum. (Allelúja, allelúja)"}],"Oratio":[{"k":"text","la":"Deus, qui beátum Gabriélem dulcíssimæ Matris tuæ dolóres assídue recólere docuísti, ac per illam sanctitátis et miraculórum glória sublimásti: da nobis, ejus intercessióne et exémplo; ita Genetrícis tuæ consociári flétibus, ut matérna ejúsdem protectióne salvémur:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Joannis Apóstoli"},{"k":"ref","la":"1 Joann 2, 14-17"},{"k":"text","la":"Caríssimi: Scribo vobis, júvenes, quóniam fortes estis, et verbum Dei manet in vobis, et vicístis malígnum. Nolíte dilígere mundum neque ea, quæ in mundo sunt. Si quis díligit mundum, non est cáritas Patris in eo: quóniam omne, quod est in mundo, concupiscéntia carnis est, et concupiscéntia oculórum, et supérbia vitæ: quæ non est ex Patre, sed ex mundo est. Et mundus transit et concupiscéntia ejus. Qui autem facit voluntátem Dei, manet in ætérnum."}],"Graduale":[{"k":"ref","la":"Ps 30:20"},{"k":"text","la":"Quam magna multitúdo dulcédinis tuæ, Dómine, quam abscondísti timéntibus te!"},{"k":"text","la":"Perfecísti eis, qui sperant in te, in conspéctu filiórum hóminum. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Minuísti eum, Dómine, paulo minus ab Angelis: glória et honóre coronásti eum: et constituísti eum super ópera mánuum tuárum. Allelúja."}],"GradualeP":[{"k":"text","la":"Alleluia, alleluia."},{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Minuísti eum. Dómine, paulo minus ab Angelis: glória et honóre coronásti eum: et constituísti eum super ópera mánuum tuárum. Allelúja."},{"k":"ref","la":"Eccli 11:24"},{"k":"text","la":"Benedíctio Dei in mercédem justi féstinat, et in hora velóci procéssus illíus fructíficat. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 30:20"},{"k":"text","la":"Quam magna multitúdo dulcédinis tuæ, Dómine, quam abscondísti timéntibus te!"},{"k":"text","la":"Perfecísti eis, qui sperant in te, in conspéctu filiórum hóminum.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 83:6-7, 11 et 13"},{"k":"text","la":"Beátus vir, cujus est auxílium abs te: ascensiónes in corde suo dispósuit, in valle lacrimárum, in loco, quem pósuit."},{"k":"text","la":"Elégi abjéctus esse in domo Dei mei: magis quam habitáre in tabernáculis peccatórum.","mark":"V"},{"k":"text","la":"Non privábit bonis eos, qui ámbulant in innocéntia: Dómine virtútum, beátus homo, qui sperat in te.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum"},{"k":"ref","la":"Marc 10:13-21"},{"k":"text","la":"In illo témpore: Offerébant Jesu parvulos, ut tángeret illos. Discípuli autem comminabántur offeréntibus. Quos cum vidéret Jesus, indígne tulit et ait illis: Sinite párvulos veníre ad me, et ne prohibuéritis eos: tálium enim est regnum Dei. Amen, dico vobis: Quisquis non recéperit regnum Dei velut párvulus, non intrábit in illud. Et compléxans eos et impónens manus super illos, benedicébat eos. Et cum egréssus esset in viam, procúrrens quidam genu flexo ante eum, rogábat eum: Magíster bone, quid fáciam, ut vitam ætérnam percípiam? Jesus autem dixit ei: Quid me dicis bonum? Nemo bonus, nisi unus Deus. Præcépta nosti: Ne adúlteris, Ne occídas, Ne furóris, Ne falsum testimónium díxeris, Ne fraudem féceris, Hónora patrem tuum et matrem. At ille respóndens, ait illi: Magíster, hæc ómnia observávi a juventúte mea. Jesus autem intúitus eum, diléxit eum et dixit ei: Unum tibi deest: vade, quæcúmque habes, vende et da paupéribus, et habébis thesáurum in cœlo: et veni, séquere me."}],"Offertorium":[{"k":"ref","la":"Ps 115:16-17"},{"k":"text","la":"O Dómine, quia ego servus tuus, et fílius ancíllæ tuæ: dirupísti víncula mea, tibi sacrificábo hóstiam laudis."}],"Secreta":[{"k":"text","la":"Salutárem hóstiam in memóriam sancti Gabriélis tibi, Dómine, offeréntes, fac nos sacrifícium mortis tuæ rite recólere: ac, méritis perdoléntis Vírginis, ejúsdem sacrifícii fructum copióse percípere:"},{"k":"macro","name":"Qui vivis"}],"Communio":[{"k":"ref","la":"Apoc. 3:20"},{"k":"text","la":"Ecce, sto ad óstium et pulso: si quis audiérit vocem meam, et aperúerit mihi jánuam, intrábo ad illum, et cenábo cum illo, et ipse mecum."}],"Postcommunio":[{"k":"text","la":"Quas tibi, Dómine, in festivitáte sancti Gabriélis Confessóris tui, pro collátis donis grátias ágimus: súscipe propítius per manus gloriósæ semper Vírginis Maríæ; ex qua carnem illam assumpsísti, cujus in hoc salutári convívio merúimus gustáre dulcédinem:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"447337b62c09cda5":{"t":"<i>Pomolimo se</i>.\nBože, koji si naučio blaženoga Gabrijela neprekidno razmatrati boli preslatke tvoje Majke i po njoj ga uzvisio slavom svetosti i čudesa, daj nam po njegovu zagovoru i primjeru tako se sjediniti s plačem tvoje Majke da se spasimo njezinom materinskom zaštitom:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si blaženoga Gabriela poučio da se ustrajno spominje boli Tvoje preslatke Majke, i koji si ga po Njoj uzvisio slavom svetosti 1 čudesa: podaj, da se po njegovom zagovoru i primjeru tako sjedinimo sa suzama Tvoje Majke, te budemo spaseni njezinom majčinskom zaštitom, koji živiš i kraljuješ ...","knRef":"Kniewald 1942, str. 516–517 (snimka 259) (OCR)"},"b166ef956c076571":{"t":"Prikazujući ti, Gospodine, na spomen svetoga Gabrijela spasonosni dar, daj da se dolično sjećamo žrtve tvoje smrti i da po zaslugama prežalosne Djevice obilno primimo plod te iste žrtve:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prinosećl Ti. Gospodine, spasonosnu žrtvu u spomen svetog Gabriela molimo, da časno svetkujemo žrtvu Tvoje smrti i da zaslugama Djevice, prepune bola, obilno zadobijemo plod iste žrtve, koji živiš i kraljuješ...","knRef":"Kniewald 1942, str. 516–517 (snimka 259) (OCR)"},"94c5973b6881cfc4":{"t":"<i>Pomolimo se</i>.\nZahvalu koju ti, Gospodine, uzdajemo o svetkovini svetoga Gabrijela priznavaoca tvoga za udijeljene darove, primi milostivo po rukama slavne vazda Djevice Marije, od koje si primio ono tijelo, kojeg smo slatkoću zavrijedili okusiti u ovoj spasonosnoj gozbi:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, milostivi Gospodine, našu zahvalu, koju Ti prinosimo o svetkovini svetog Gabrijela. Tvojeg priznavaoca, za darove, koje si nam podijelio po slavnoj vazda Djevici Mariji, od koje Ei uzeo tijelo, kojega smo slatkoću zaslužili okusiti u ovoj spasonosnoj gozbi, po G, n.","knRef":"Kniewald 1942, str. 516–517 (snimka 259) (OCR)"},"5b4b6653b856c93a":{"t":"Sir 11, 13, Ps 72, 1\n(Sir 11, 13) Oko ga je Božje ljubazno pogledalo. Bog ga je podigao iz poniženja i uzvisio. Mnogi su se tome divili i slavili Boga. (Ps 72, 1) Kako je dobar Bog za Izraela, za sve one koji su pravedna srca!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 11, 13) Oko ga je Božje ljubazno pogledalo. Bog ga je podigao iz poniženja i uzvisio. Mnogi su se tome divili i slavili Boga.","kn":"(Crkv. 11, 13). Oko je Božje bacilo pogled na nij i Gosjpodin ga je uzvisio iz njegova poniženja i uzdignuo je njegovu glavu i zadivili su se mnogi i odali su čast Bogu. (Ps. 72, 1). Gospodin je tako dobar svome puku, onima, koji su čista srca. Slava Ocu . . . Oko je Božje . . .","knRef":"Kniewald 1942, str. 514–515 (snimka 258) (OCR)"},"661203f21edeb225":{"t":"1 Iv 2, 14-17\nČitanje Poslanice bl. Ivana apostola. Predragi, pišem vama, mladići, jer ste jaki. Božja nauka je u vama i pobijedili ste zlo. Nemojte ljubiti ni svijeta, ni ono što je u svijetu. Ako tko ljubi svijet, u njem nema Očeve ljubavi. Ništa od onoga što je u svijetu: ni požuda tijela, ni požuda očiju, ni oholost života nije od Oca nego od svijeta. Prolazan je svijet i njegova požuda, a tko vrši volju Božju ostaje zauvijek.","kn":"Čitanje poslanice blaženoga Ivana apostola (I. 2- 14-7). Predragi; pisah vam, mladići, jer ste jaki, I riječ Božja u vama ostaje, i pobijedili ste onoga, koji je zao. Ne ljubite svijeta ni što je na svijetu, jer sve, što je na svijetu, požuda je tijela i požuda očiju, i oholost života; to nije od Oca, nego je od ovoga svijeta. I svijet prolazi i požuda njegova, a tko čini volju Božju, ostaje do vijeka.","knRef":"Kniewald 1942, str. 516–517 (snimka 259) (OCR)"},"8f4b1089dabee1a2":{"t":"Ps 30, 20\nKako je veliko obilje miline tvoje, Gospodine, što je čuvaš za one koji te se boje! Daješ je onima koji se u te uzdaju pred sinovima ljudskim.\n\nPs 83, 6-7, 11 i 13\nBlago čovjeku kojemu je jakost od tebe, u svom srcu slijedi tvoje putove, prolazeći dolinom suza pretvara je u izvor. Volim biti odbačen u domu Boga mojega, nego stanovati u šatorima grješničkim. On ne uskraćuje dobara onima koji žive bezazleno. Gospodine nad vojskama, blago čovjeku koji se uzda u tebe!","kn":"(Ps. 30, 20). Kako je veliko obilje miline Tvoje, Gospodine, što je čuvaš za one, koji Te se boje, što je daješ onima, koji se u Te uzdaju pred sinovima ljudskim.\n\n(Ps. 83, 6-7, 11, 13). Blago ljudima, kojima je jakost od Tebe, u svom srcu slijedi Tvoje putove: prolazeći dolinom suza pretvaraju je u izvor. Volim biti odbačen u domu Boga svojega, nego stanovati u stanovima grješničkim. Ne uzima Gospodin dobara onima, koji hode u bezazlenosti. Gospodine nad vojskama, blago čovjeku, koji se ufa u Te.","knRef":"Kniewald 1942, str. 516–517 (snimka 259) (OCR)"},"18a69dbbf863593e":{"t":"Mk 10, 13-21\nSlijedi sveto Evanđelje po Marku. U ono vrijeme donosili su Isusu djecu da ih se dotakne. Učenici su to sprečavali. Kada ih je vidio Isus, nije mu bilo drago pa im reče: Pustite da djeca dođu k meni i ne priječite im, jer takvih je Božje kraljevstvo. Zaista vam kažem: Tko ne primi Božjega kraljevstva kao dijete ne će uči u njega. I grleći ih i postavljajući na njih ruke blagoslivljao ih je. Kada je pošao dalje, netko pritrči, klekne preda nj i upita ga: Dobri učitelju, što mi je činiti da zadobijem vječni život? Isus mu reče: Što me zoveš dobrim? Nitko nije dobar nego jedini Bog, Poznaš zapovijedi: Ne čini preljuba, ne ubij, ne kradi, ne svjedoči lažno, ne varaj, poštuj svojega oca i majku. A onaj mu odgovori: Učitelju, sve sam to obdržavao od svoje mladosti. Isus ga pogleda, zavoli i reče mu: Jedno ti još treba: Pođi, prodaj sve što imaš, podijeli siromasima i steći ćeš blago na nebu. Tada dođi i hajde za mnom.","kn":"t Slijedi sv. evanđelje po Marku (10, 13r21). U ono vrijeme donosili su Isusu djecu, da ih se dotakne A učenici su branili onima, što.su ih donosili. A kad to Isus vidje, ne bi mu milo, pa im reče; Pustite djecu, neka dolaze k meni, i ne branite lm, jer je takovih kraljevstvo Božje. Zaista vam ka žem: tko ne primi kraljevstva Božjega kao dijete, ne će ući u nj. I zagrlivši ih stavi ruke na njih, te ih blagoslovi. I kad iziđe na put, pritrča netko i kleknuvši pred njim moljaše ga: Učitelju dobri, što mi valja činiti, da dobijem život vječni? A Isus mu reče: Što me zoveš dobrim? Niko nije dobar osim jedinoga Boga. Znadeš zapovijedi: ne ubij, ne čini preljube, ne ukradi, ne reci lažnoga svjedočanstva, ne prevari, poštuj oca svoga i mater! A on mu odgovori: Učitelju! sve sam ovo izvršio od svoje mladosti. A Isus pogledavši na nj zavoli ga i reče mu: Jedno ti nedostaje: idi, prodaj sve što imaš i podaj siromasima i imat ćeš blago na nebu, i dodi, uzmi križ svoj te idi za mnom!","knRef":"Kniewald 1942, str. 516–517 (snimka 259) (OCR)"},"5bdf5ee92ba9ef6f":{"t":"Ps 115, 16-17\nGospodine, ja sam sluga tvoj i sin službenice tvoje. Ti si rastrgao okove moje, a ja ću ti prinijeti žrtvu hvale.","kn":"(Ps; 115, 16-7). Gospodine, ja sam Tvoj službenik i sin Tvoje službenice: Ti si rastrgao moje okove 1 ja ću Ti prinijetl žrtvu hvale.","knRef":"Kniewald 1942, str. 516–517 (snimka 259) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"7d3e1899f148a279":{"t":"Otk 3, 20\nEvo stojim na vratima i kucam. Ako tko čuje glas moj i otvori mi vrata, ući ću k njemu i večerati s njim, a on sa mnom.","kn":"(Otkr. 3, 20). Evo, stojim na vratima i kucam: ako tko čuje glas moj i otvori vrata, ući ću k njemu i večerat ću s njim, i on sa mnom.","knRef":"Kniewald 1942, str. 516–517 (snimka 259) (OCR)"}}});
